<script lang="ts">
 import {defaultInvestigationState,defaultExampleState,reconcileOrder,type InvestigationState} from './investigationNavigation';
 import type {Model} from './types';
 import {transitionMetrics,repeatMetrics,prefixTree,rankedPathGroups,defaultPreferences,type Criterion,type Preferences,type Population,type PopulationCoverage,type InvestigationObservation} from './investigation';
 import {loopProjection} from './journeyViews';
 import {edgeKey} from './graph';
 import {dateTime} from './helpers';
 import {translate,type Language} from './i18n';
 import Modal from './Modal.svelte';
 import MatchingExamples from './MatchingExamples.svelte';
 import JourneyStory from './JourneyStory.svelte';
 import InvestigationSummary from './InvestigationSummary.svelte';
 let {view,model,language,selectedStep='',selectedEdge='',onedge,onjourney,partial=false,label,population='current',coverage,preferences=$bindable(defaultPreferences()),chosen=$bindable(''),stages=$bindable<string[]>([]),stagesInitialized=$bindable(false),expanded=$bindable<string[]>([]),commonDomain=0,availableStages=[],criterion=$bindable<Criterion|null>(null),ontrace,oncriterion,oncopy,onrescale,transient=$bindable(defaultInvestigationState())}:{view:string;model:Model;language:Language;selectedStep?:string;selectedEdge?:string;onedge:(a:string,b:string,p?:Population)=>void;onjourney:(id:string)=>void;partial?:boolean;label:string;population?:Population;coverage?:PopulationCoverage;preferences?:Preferences;chosen?:string;stages?:string[];stagesInitialized?:boolean;expanded?:string[];commonDomain?:number;availableStages?:string[];criterion?:Criterion|null;transient?:InvestigationState;ontrace?:(trace:string,population:Population,journey:string)=>void;oncriterion?:(c:Criterion,p:Population)=>void;oncopy?:(c:Criterion,p:Population,observation:InvestigationObservation)=>void;onrescale?:()=>void}=$props();
 const t=(s:string)=>translate(s,language);
 let localDomain=$state(0);
 const trace=(id:string,journey:string)=>ontrace?.(id,population,journey);
 const transitions=$derived(transitionMetrics(model.journeys));
 const edgeMap=$derived(new Map(transitions.map(e=>[edgeKey(e.from,e.to),e])));
 const allStages=$derived([...new Set([...availableStages,...model.journeys.flatMap(j=>(j.steps??[]).map(s=>s.step))])].sort());
 const traffic=$derived.by(()=>{const counts=new Map<string,number>();for(const j of model.journeys)for(const step of j.steps??[])counts.set(step.step,(counts.get(step.step)??0)+1);return counts});
 const selectedEndpoints=$derived.by(()=>{try{const pair=JSON.parse(selectedEdge);return Array.isArray(pair)&&pair.length===2&&pair.every(s=>typeof s==='string')?pair as string[]:[]}catch{return []}});
 const initial=$derived([...new Set([selectedStep,...selectedEndpoints,...preferences.stages,...[...allStages].sort((a,b)=>(traffic.get(b)??0)-(traffic.get(a)??0)||a.localeCompare(b))].filter(s=>s&&allStages.includes(s)))].slice(0,preferences.stages.length?32:12));
 const shown=$derived((stagesInitialized||stages.length?stages:initial).filter(s=>allStages.includes(s)).slice(0,32));
 const searchResults=$derived(allStages.filter(s=>s.toLocaleLowerCase().includes(transient.search.toLocaleLowerCase())));
 const selectedOrigin=$derived(selectedEndpoints[0]??selectedStep);
 const selectedDestination=$derived(selectedEndpoints[1]??'');
 const metric=$derived(preferences.metric);
 $effect(()=>{if(!stagesInitialized&&(stages.length||initial.length)){if(!stages.length)stages=initial;stagesInitialized=true}});
 const unit=$derived(metric==='occurrences'?'Transition occurrences':metric==='journeys'?'Affected journeys':metric==='visits'?'Affected visits':'Outgoing occurrence share');
 const limited=$derived(partial||!!coverage?.sourcePartial||model.journeys.some(j=>j.partial||(j.steps??[]).some(s=>s.gapBefore)));
 const repeats=$derived(repeatMetrics(model.journeys).sort((a,b)=>transient.repeatSort==='prevalence'?(b.prevalence??0)-(a.prevalence??0):transient.repeatSort==='extras'?b.extras-a.extras:b.affected-a.affected));
 const returns=$derived(loopProjection(model.journeys).returns);
 const tree=$derived(prefixTree(model.journeys,new Set(expanded),preferences.groupRepeats,transient.maxDepth,5,transient.prefixOrder));
 $effect(()=>{const order=reconcileOrder(transient.prefixOrder,tree.order);if(JSON.stringify(order)!==JSON.stringify(transient.prefixOrder))transient.prefixOrder=order});
 const rankedPaths=$derived(rankedPathGroups(model.journeys));
 const selected=$derived(model.journeys.find(j=>j.id===chosen));
 function value(e:typeof transitions[number]|undefined,origin=''){if(!e&&metric==='share'&&!transitions.some(x=>x.from===origin))return null;return e?(metric==='share'?e.share:e[metric]):limited?null:0}
 function numeric(v:number|null|undefined){return v==null?'—':metric==='share'?(v*100).toFixed(1)+'%':String(v)}
 const maximum=$derived(Math.max(metric==='share'?0.01:1,...transitions.map(e=>value(e)??0)));
 const rankedTransitions=$derived([...transitions].sort((a,b)=>(value(b)??-1)-(value(a)??-1)||a.from.localeCompare(b.from)||a.to.localeCompare(b.to)));
 const domain=$derived(commonDomain||localDomain||maximum);
 const invokerId=(c:Criterion,suffix='')=>'investigation-invoker-'+population+'-'+encodeURIComponent(JSON.stringify(c))+suffix;
 function examples(c:Criterion){transient.examples=defaultExampleState();const invoker=document.activeElement;if(invoker instanceof HTMLElement){if(!invoker.id)invoker.id=invokerId(c);transient.examples.invoker=invoker.id;}criterion=c;oncriterion?.(c,population)}
 function include(s:string){if(shown.includes(s))return;const protectedStages=new Set([selectedStep,...selectedEndpoints]);const remove=shown.length>=32?shown.find(stage=>!protectedStages.has(stage)):undefined;stages=[...shown.filter(stage=>stage!==remove),s];stagesInitialized=true}
 function reorder(){stages=[...shown].sort((a,b)=>preferences.sort==='alphabetic'?a.localeCompare(b):(traffic.get(b)??0)-(traffic.get(a)??0)||a.localeCompare(b))}
 function cellKey(event:KeyboardEvent,row:number,col:number){let r=row,c=col;const last=shown.length-1;if(event.key==='ArrowRight')c=Math.min(last,c+1);else if(event.key==='ArrowLeft')c=Math.max(0,c-1);else if(event.key==='ArrowDown')r=Math.min(last,r+1);else if(event.key==='ArrowUp')r=Math.max(0,r-1);else if(event.key==='Home')c=0;else if(event.key==='End')c=last;else return;event.preventDefault();transient.focusCell=r+':'+c;document.getElementById('cell-'+population+'-'+transient.focusCell)?.focus()}
 function toggle(key:string){expanded=expanded.includes(key)?expanded.filter(k=>k!==key):[...expanded,key]}
</script>
<section class="loop-view investigation-view" data-population={population} aria-label={t(label)}>
 <header><h2><span class="population-badge">{population==='live'?'L':population==='baseline'?'B':'•'}</span> {t(label)}</h2><p>{model.journeys.length} {t('Retained journeys in this selection')}</p></header>
 {#if coverage}<p>{coverage.scope?t('Selected visit'):t('All app traffic')} · {dateTime(coverage.from)} → {dateTime(coverage.to)} · v{coverage.definitions.join(', ')||'—'} · {t(coverage.selectionPolicy==='evidence-window'?'Evidence window':'Captured start cohort')}</p>{/if}
 {#if limited}<p class="warning">{t('Coverage is partial. Counts describe available retained evidence only.')}</p>{/if}
 {#if model.journeys.some(j=>j.partial||j.rightCensored)}<p class="warning">{t('Some journeys have a partial beginning or continuation; earlier visits may be missing.')}</p>{/if}
 {#if model.journeys.length===1}<button id={'one-journey-'+population} class="secondary" onclick={()=>examples({kind:'all'})}>{t('Inspect the one retained journey')}</button>{/if}
 {#if !model.journeys.length}<p>{t('No retained journey detail in this selection.')}</p><p>{t('Inspect received records, clear restrictive filters or choose retained dates. Summaries cannot reconstruct ordered detail.')}</p>{/if}
 {#if view==='journey-timeline'}
  <label>{t('Choose a journey')}<select bind:value={chosen} onchange={()=>{transient.story={expanded:[]};oncriterion?.({kind:'all'},population)}}><option value="">{t('Choose a journey')}</option>{#each model.journeys as j}<option value={j.id}>{dateTime(j.start)} · {j.path.slice(0,5).join(' → ')} · {j.id.slice(-12)}</option>{/each}</select></label>
  <label class="toggle"><input type="checkbox" bind:checked={preferences.groupRepeats}/><span>{t('Group consecutive repeats')}</span></label>
  {#if selected}<JourneyStory journey={selected} {model} {language} group={preferences.groupRepeats} ontrace={trace} bind:transient={transient.story}/>{:else}<p>{t('Choose an available journey to see its ordered steps. Expired detail cannot be reconstructed.')}</p><button id={'browse-journeys-'+population} class="secondary" onclick={()=>examples({kind:'all'})}>{t('Browse matching journeys')}</button>{/if}
 {:else if view==='matrix'}
  <p>{t('Where do journeys go directly after a stage? Select a cell for matching examples.')}</p>
  <div class="investigation-controls"><label>{t('Primary metric')}<select bind:value={preferences.metric} onchange={()=>localDomain=0}>{#each [['occurrences','Transition occurrences'],['journeys','Affected journeys'],['visits','Affected visits'],['share','Outgoing occurrence share']] as [id,name]}<option value={id}>{t(name)}</option>{/each}</select></label><label>{t('Stage search')}<input type="search" bind:value={transient.search}/></label><label>{t('Stage order')}<select value={preferences.sort==='alphabetic'?'alphabetic':'traffic'} onchange={event=>preferences.sort=event.currentTarget.value}><option value="traffic">{t('Traffic')}</option><option value="alphabetic">{t('Alphabetical')}</option></select></label><button class="secondary" onclick={reorder}>{t('Reorder explicitly')}</button></div>
  {#if transient.search}<ul class="stage-search">{#each searchResults.slice(0,20) as s}<li><button class="text-button" disabled={shown.includes(s)} onclick={()=>include(s)}>{s} · {t('Include stage')}</button></li>{/each}</ul><p>{Math.min(20,searchResults.length)}/{searchResults.length} {t('Search results shown')} · {t('Search is limited to stages in the retained source projection.')}</p>{/if}
  <p>{shown.length}/{allStages.length} {t('Displayed stages')} · {allStages.length-shown.length} {t('omitted stages')} · {t('Maximum displayed stages')}: 32</p>
  {#if !shown.length}<p>{t('No stages selected. Search for a stage to include it.')}</p>{/if}
  <div class="stage-chips">{#each shown as s}<button class="secondary" onclick={()=>stages=shown.filter(x=>x!==s)}>{s} ×</button>{/each}</div>
  <p>{t(unit)} · {t('Linear scale')}: 0 → {numeric(domain)} <button class="text-button" onclick={()=>{localDomain=maximum;onrescale?.()}}>{t('Rescale')}</button>{#if maximum>domain}<strong>{t('Intensity capped; exact counts remain visible.')}</strong>{/if}</p>
  <p>{t('Arrow keys move between cells; Home/End move within a row; Enter inspects. Tab exits the matrix.')}</p><p>{t('Outgoing shares include all retained direct outgoing occurrences, including hidden destinations and self-transitions. A zero denominator is unavailable.')}</p>
  <div class="table-wrap heatmap-region" role="region" aria-label={t('Transition heatmap')}><table class="heatmap"><caption>{t(unit)} · {t(label)}</caption><thead><tr><th>{t('From / to')}</th>{#each shown as s}<th scope="col" class:selected-axis={s===selectedDestination}>{s}{#if s===selectedDestination}<small> · {t('Selected destination')}</small>{/if}</th>{/each}</tr></thead><tbody>{#each shown as a,r}<tr><th scope="row" class:selected-axis={a===selectedOrigin}>{a}{#if a===selectedOrigin}<small> · {t('Selected origin')}</small>{/if}</th>{#each shown as b,c}{@const e=edgeMap.get(edgeKey(a,b))}{@const v=value(e,a)}<td data-from={a} data-to={b} data-value={v??'unavailable'} data-domain={domain} class:selected-cell={selectedEdge===edgeKey(a,b)} style:background={v==null?'repeating-linear-gradient(45deg,transparent,transparent 3px,#64748b20 3px,#64748b20 5px)':`color-mix(in srgb,var(--population-color) ${Math.max(0,Math.min(55,55*v/domain))}%, var(--surface))`}><button id={'cell-'+population+'-'+r+':'+c} tabindex={transient.focusCell===r+':'+c?0:-1} aria-label={`${t(label)}; ${a} → ${b}; ${numeric(v)} ${t(unit)}; ${e?.denominator??0} ${t('Observed outgoing occurrences')}; ${limited?t('Observed partial evidence'):t('Retained source')}`} aria-pressed={selectedEdge===edgeKey(a,b)} onfocus={()=>transient.focusCell=r+':'+c} onkeydown={event=>cellKey(event,r,c)} onclick={()=>{onedge(a,b,population);if(e)examples({kind:'transition',from:a,to:b})}}>{numeric(v)}</button></td>{/each}</tr>{/each}</tbody></table></div>
  <details open><summary>{t('Ranked destinations and supporting evidence')}</summary><table><thead><tr><th>{t('Transition')}</th><th>{t(unit)}</th><th>{t('Denominator')}</th><th>{t('Evidence')}</th></tr></thead><tbody>{#each rankedTransitions.filter(e=>!selectedStep||e.from===selectedStep).slice(0,100) as e}<tr><th>{e.from} → {e.to}</th><td>{numeric(value(e))}</td><td>{e.denominator} {t('Observed outgoing occurrences')}</td><td><button id={invokerId({kind:'transition',from:e.from,to:e.to})} class="text-button" onclick={()=>{onedge(e.from,e.to,population);examples({kind:'transition',from:e.from,to:e.to})}}>{t('Matching journeys')} ({e.journeys})</button></td></tr>{/each}</tbody></table>{#if transitions.length>100}<p>{t('Ranked list limited to 100 transitions; select an origin or narrow filters.')}</p>{/if}</details>
 {:else if view==='repeats'}
  <p>{t('Repeats are additional occurrences in a journey. Returns are direct transitions to a different previously observed stage. Repetition is not automatically a problem.')}</p>
  <label>{t('Repeat ranking')}<select bind:value={transient.repeatSort} onchange={()=>oncriterion?.(criterion??{kind:'all'},population)}><option value="journeys">{t('Affected journeys')}</option><option value="prevalence">{t('Prevalence')}</option><option value="extras">{t('Additional occurrences')}</option></select></label>
  <table><caption>{t('Repeated stages')}</caption><thead><tr><th>{t('Stage')}</th><th>{t('Additional occurrences')}</th><th>{t('Prevalence')}</th><th>{t('Intensity')}</th><th>{t('Evidence')}</th></tr></thead><tbody>{#each repeats.slice(0,100) as r}<tr><th>{r.stage}</th><td>{r.extras} · {r.total} {t('total occurrences')}</td><td>{r.affected}/{r.reaching} · {((r.prevalence??0)*100).toFixed(1)}%</td><td>{r.intensity?.toFixed(2)} {t('extras per repeating journey')}</td><td><button id={invokerId({kind:'repeat',stage:r.stage})} class="text-button" onclick={()=>examples({kind:'repeat',stage:r.stage})}>{t('Matching journeys')} ({r.affected})</button></td></tr>{/each}</tbody></table>
  <p>{t('Prevalence uses repeating journeys / journeys reaching the stage. Small denominators and partial beginnings limit interpretation.')}</p>
  <h3>{t('Return transitions')}</h3>{#if !returns.length}<p>{t('No qualifying non-self returns observed in retained evidence.')}</p>{:else}<ul>{#each returns.slice(0,100) as r}<li>{r.from} → {r.to} · {r.occurrences} {t('Occurrences')} · <button id={invokerId({kind:'return',from:r.from,to:r.to})} class="text-button" onclick={()=>examples({kind:'return',from:r.from,to:r.to})}>{r.journeyIds.length} {t('Matching journeys')}</button></li>{/each}</ul>{/if}
 {:else if view==='sequence'}
  <p>{t('Which ordered beginnings do journeys share? Prefix support is not exact path-group membership.')}</p>
  <div class="investigation-controls"><label class="toggle"><input type="checkbox" bind:checked={preferences.groupRepeats}/><span>{t('Group consecutive repeats')}</span></label><label>{t('Initial ordinal steps')}<select bind:value={transient.maxDepth}><option value={3}>3</option><option value={8}>8</option><option value={32}>32</option></select></label></div>
  <button class="secondary" onclick={()=>transient.prefixOrder=[]}>{t('Reorder explicitly')}</button>
  <p>{t('Bounded path exploration')}: 32 {t('steps')} · 200 {t('visible prefix nodes')} · 5 {t('initial children per parent')}</p>
  {#if tree.rootBranches>5}<button class="text-button" onclick={()=>toggle('[]/*')}>{t('More starting branches')} ({tree.rootBranches})</button>{/if}
  <ol class="prefix-tree">{#each tree.nodes as n (n.key)}<li style:margin-left={`${Math.min(n.depth-1,6)}rem`}><strong>{n.depth}. {n.labels.at(-1)}</strong> · {n.journeyIds.length} {t('Journeys sharing this prefix')} / {tree.total} <progress max={Math.max(1,tree.total)} value={n.journeyIds.length}></progress>{#if n.children}<button class="text-button" aria-expanded={expanded.includes(n.key)} onclick={()=>toggle(n.key)}>{t(expanded.includes(n.key)?'Collapse':'Expand')} ({n.children})</button>{#if n.children>5}<button class="text-button" onclick={()=>{if(!expanded.includes(n.key))expanded=[...expanded,n.key];toggle(n.key+'/*')}}>{t('More branches')}</button>{/if}{/if}<button id={invokerId(n.criterion)} class="text-button" onclick={()=>examples(n.criterion)}>{t('Matching journeys')}</button>{#if n.closed}<small>{n.closed} {t('Captured closures')}</small>{/if}{#if n.active}<small>{n.active} {t('Active')}</small>{/if}{#if n.censored}<small>{n.censored} {t('Continuation is outside this view.')}</small>{/if}{#if n.inactive}<small>{n.inactive} {t('Inactive; no captured closure')}</small>{/if}{#if n.gap}<small>{n.gap} {t('Source gap')}</small>{/if}{#if n.capped}<small>{n.capped} {t('Display cap')}</small>{/if}</li>{/each}</ol>
  {#if tree.omitted}<p>{t('Other branch support omitted at visible limits')}: {tree.omitted} <button class="text-button" onclick={()=>examples({kind:'all'})}>{t('Browse all retained paths')}</button></p>{/if}
  <details><summary>{t('Ranked paths')}</summary><ol>{#each rankedPaths.groups as p}<li>{p.path.join(' → ')} · {p.members} {t('Displayed group members')} / {rankedPaths.total} ({(100*p.members/Math.max(1,rankedPaths.total)).toFixed(1)}%) · {p.prefixSupport} {t('Journeys sharing this prefix')} · {p.exactSupport} {t('Exact captured-path members')}
   {#if p.closed}<small>{p.closed} {t('Captured closures')}</small>{/if}{#if p.active}<small>{p.active} {t('Active')}</small>{/if}{#if p.censored}<small>{p.censored} {t('Continuation is outside this view.')}</small>{/if}{#if p.inactive}<small>{p.inactive} {t('Inactive; no captured closure')}</small>{/if}{#if p.gap}<small>{p.gap} {t('Source gap')}</small>{/if}{#if p.capped}<small>{p.capped} {t('Display cap')}</small>{/if}{#if p.partial}<small>{p.partial} {t('partial')}</small>{/if}
   <button id={invokerId({kind:'prefix',path:p.path},'-ranked')} class="text-button" onclick={()=>examples({kind:'prefix',path:p.path})}>{t('Inspect prefix support')}</button>{#if p.exactSupport}<button id={invokerId({kind:'exact',path:p.path},'-ranked')} class="text-button" onclick={()=>examples({kind:'exact',path:p.path})}>{t('Inspect exact captured paths')}</button>{/if}</li>{/each}</ol>
   {#if rankedPaths.omittedGroups}<p>{t('Other path groups')}: {rankedPaths.omittedGroups} · {rankedPaths.omittedMembers} {t('Displayed group members')} <button class="text-button" onclick={()=>examples({kind:'all'})}>{t('Browse all retained paths')}</button></p>{/if}
   <p>{t('Display-limited groups are not exact completed paths; prefix examples can include longer continuations.')}</p><p>{t('Group share uses all retained journeys. Prefix support and exact captured-path support overlap; do not add them.')}</p></details>
 {/if}
 <InvestigationSummary {model} {criterion} {population} {coverage} metric={preferences.metric} {language} {selectedStep} {selectedEdge} onexamples={examples} {oncopy}/>
</section>
{#if criterion}<Modal title={t('Matching journeys')} wide returnFocusId={transient.examples.invoker} fallbackFocusId={'investigation-view-'+view} onclose={()=>criterion=null}><MatchingExamples {model} {criterion} {language} population={label} group={preferences.groupRepeats} ontrace={trace} bind:transient={transient.examples}/></Modal>{/if}

